    if (w.length < 3) fail(`error: line ${n}: expected dep <name> <dependency>...`)
    depLines.push(w.slice(1))
  } else fail(`error: line ${n}: unknown directive ${w[0]}`)
}

const deps = new Map()
for (const k of cost.keys()) deps.set(k, new Set())
for (const names of depLines) {
  for (const x of names) if (!cost.has(x)) fail(`error: unknown task ${x}`)
  for (const d of names.slice(1)) deps.get(names[0]).add(d)
}
const names = [...cost.keys()].sort(cmp)
const sdeps = new Map(names.map((k) => [k, [...deps.get(k)].sort(cmp)]))

// cycle detection
{
  const state = new Map()
  const stack = []
  const visit = (u) => {
    state.set(u, 1)
    stack.push(u)
    for (const v of sdeps.get(u)) {
      const s = state.get(v)
      if (s === 1) {
        const cyc = stack.slice(stack.indexOf(v)).concat(v)
