    d = Math.max(d, depth.get(v) + 1)
  }
  start.set(u, s); finish.set(u, s + cost.get(u)); depth.set(u, d)
  if (finish.get(u) > total) total = finish.get(u)
}

const out = []
if (mode === 'waves') {
  const ws = []
  for (const k of names) (ws[depth.get(k)] ||= []).push(k)
  ws.forEach((w, i) => out.push(`wave ${i}: ${w.join(' ')}`))
  out.push(`total ${total}`)
} else if (mode === 'explain') {
  for (const k of names) out.push(`${k} start=${start.get(k)} finish=${finish.get(k)} depth=${depth.get(k)}`)
  out.push(`total ${total}`)
} else {
  const prio = new Map()
  const rev = [...order].reverse()
  const dependents = new Map(names.map((k) => [k, []]))
  for (const k of names) for (const d of sdeps.get(k)) dependents.get(d).push(k)
  for (const u of rev) {
    let m = 0n
    for (const v of dependents.get(u)) if (prio.get(v) > m) m = prio.get(v)
    prio.set(u, m + cost.get(u))
  }
  const fin = new Map()
  const free = new Array(workers).fill(0n)
  const ran = Array.from({ length: workers }, () => [])
  const pending = new Set(names)
  let t = 0n, makespan = 0n
  while (pending.size) {
    for (;;) {
      const wi = free.findIndex((f) => f <= t)
      if (wi < 0) break
      let best = null
      for (const k of names) {
        if (!pending.has(k)) continue
        if (!sdeps.get(k).every((d) => fin.has(d) && fin.get(d) <= t)) continue
        if (best === null || prio.get(k) > prio.get(best)) best = k
      }
      if (best === null) break
      pending.delete(best)
      const f = t + cost.get(best)
      fin.set(best, f)
      free[wi] = f
      ran[wi].push(`${best}@${t}-${f}`)
      if (f > makespan) makespan = f
    }
    if (!pending.size) break
    let next = null
    for (const f of free) if (f > t && (next === null || f < next)) next = f
    if (next === null) break
    t = next
  }
  ran.forEach((r, i) => out.push(`worker ${i}:` + r.map((x) => ' ' + x).join('')))
  out.push(`makespan ${makespan}`)
}
process.stdout.write(out.join('\n') + '\n')
